import csv, datetime, math
from collections import defaultdict
rows=list(csv.DictReader(open("data.csv")))
by=defaultdict(dict); dates={}
for r in rows:
    by[r["band"]][r["period_id"]]=float(r["y"]); dates[r["period_id"]]=r["date"]
pids=sorted(by["VH"].keys())
def d(s): return datetime.date.fromisoformat(s)
D={p:d(dates[p]) for p in pids}
bands=["VH","VV","VV-VH"]

# Backtest: train on pids with date <= cutoff, predict pids in (cutoff, cutoff+1yr]
def backtest(cutoff):
    train=[p for p in pids if D[p]<=cutoff]
    test=[p for p in pids if cutoff<D[p]<=cutoff+datetime.timedelta(days=370)]
    res={}
    for b in bands:
        # persistence
        last=by[b][train[-1]]
        # climatology: monthly mean from train
        mm=defaultdict(list)
        for p in train: mm[D[p].month].append(by[b][p])
        # seasonal naive: nearest train pid ~365 earlier
        preds={}
        for p in test:
            preds[p]={}
            preds[p]["persist"]=last
            preds[p]["clim"]=sum(mm[D[p].month])/len(mm[D[p].month])
            tgt=D[p]-datetime.timedelta(days=365)
            cands=[(abs((D[q]-tgt).days),q) for q in train]
            gap,q=min(cands)
            preds[p]["seas"]=by[b][q]
        for meth in ["persist","clim","seas"]:
            errs=[by[b][p]-preds[p][meth] for p in test]
            rmse=math.sqrt(sum(e*e for e in errs)/len(errs))
            res[(b,meth)]=rmse
    return res,len(test)

for cutoff in [datetime.date(2022,9,21),datetime.date(2023,9,21)]:
    res,n=backtest(cutoff)
    print("cutoff",cutoff,"ntest",n)
    for b in bands:
        print(" ",b,{m:round(res[(b,m)],3) for m in ["persist","clim","seas"]})
