import csv, datetime, math
from collections import defaultdict
rows=list(csv.DictReader(open("data.csv")))
by=defaultdict(dict); dates={}
for r in rows:
    by[r["band"]][r["period_id"]]=float(r["y"]); dates[r["period_id"]]=r["date"]
pids=sorted(by["VH"].keys())
def d(s): return datetime.date.fromisoformat(s)
D={p:d(dates[p]) for p in pids}
bands=["VH","VV","VV-VH"]

def backtest(cutoff):
    train=[p for p in pids if D[p]<=cutoff]
    test=[p for p in pids if cutoff<D[p]<=cutoff+datetime.timedelta(days=370)]
    res={}
    for b in bands:
        mm=defaultdict(list)
        for p in train: mm[D[p].month].append(by[b][p])
        clim={m:sum(v)/len(v) for m,v in mm.items()}
        # recent window (last 8) offset from climatology
        recent=train[-8:]
        off=sum(by[b][p]-clim[D[p].month] for p in recent)/len(recent)
        # trend: linear fit on time index
        xs=[(D[p]-D[train[0]]).days for p in train]
        ys=[by[b][p] for p in train]
        n=len(xs); mx=sum(xs)/n; my=sum(ys)/n
        slope=sum((x-mx)*(y-my) for x,y in zip(xs,ys))/sum((x-mx)**2 for x in xs)
        preds={}
        for p in test:
            c=clim[D[p].month]
            preds[p]={"lcc":c+off,
                      "trend":my+slope*((D[p]-D[train[0]]).days-mx),
                      "lcc_trend":c+off+slope*((D[p]-D[train[0]]).days-mx)}
        for meth in ["lcc","trend","lcc_trend"]:
            errs=[by[b][p]-preds[p][meth] for p in test]
            res[(b,meth)]=math.sqrt(sum(e*e for e in errs)/len(errs))
    return res,len(test)

for cutoff in [datetime.date(2022,9,21),datetime.date(2023,9,21)]:
    res,n=backtest(cutoff)
    print("cutoff",cutoff,"ntest",n)
    for b in bands:
        print(" ",b,{m:round(res[(b,m)],3) for m in ["lcc","trend","lcc_trend"]})
