import csv, datetime, statistics, math
rows=list(csv.DictReader(open("data.csv")))
data={}; dates={}
for r in rows:
    data.setdefault(r["band"],{})[r["period_id"]]=float(r["y"])
    dates[r["period_id"]]=datetime.date.fromisoformat(r["date"])
ks=sorted(dates)
bands=list(data)

def clim(hist_ks, b, d, halfwidth=20):
    # weighted mean of values within +-halfwidth days of day-of-year, circular
    num=den=0.0
    for k in hist_ks:
        dd=dates[k]
        diff=abs((dd-d).days)
        diff=min(diff, 365-diff)
        if diff<=halfwidth:
            w=math.exp(-0.5*(diff/(halfwidth/2))**2)
            num+=w*data[b][k]; den+=w
    return num/den if den else None

def backtest(split_idx, model):
    hist=ks[:split_idx]; fut=ks[split_idx:]
    errs={b:[] for b in bands}
    for b in bands:
        for k in fut:
            p=model(hist,b,dates[k])
            errs[b].append((p-data[b][k])**2)
    return {b:round(math.sqrt(statistics.mean(e)),3) for b,e in errs.items()}

def persistence(hist,b,d): return data[b][hist[-1]]
