def interp_year(pts, target_doy):
    if not pts: return None
    n=len(pts)
    for i in range(n):
        d0,v0 = pts[i]
        d1,v1 = pts[(i+1)%n]
        if i==n-1: d1+=365
        if d0 <= target_doy <= d1:
