            t=(target_doy-d0)/(d1-d0)
            return v0+t*(v1-v0)
    d0,v0=pts[-1]; d1,v1=pts[0]; d0-=365
    if d0<=target_doy<=d1:
        t=(target_doy-d0)/(d1-d0); return v0+t*(v1-v0)
