    years=sorted(ys)
    errs=[]
    for hy in years:
        train=[y for y in years if y!=hy]
        if not train: continue
        for d,v in data[band].items():
            if d.year!=hy: continue
            if method=="clim":
                pred=predict_clim(ys,train,doy(d))
            elif method=="recent":
                # weight recent years more
                w={y:0.5**(max(train)-y) for y in train}
                pred=predict_clim(ys,train,doy(d),w)
            elif method=="lastyear":
                pred=interp_year(ys[max(train)],doy(d))
            if pred is not None:
                errs.append((v-pred)**2)
    return math.sqrt(sum(errs)/len(errs)) if errs else None

