def predict_doy(hist, target, window):
    # hist: list of (date,val) all before target; gather within +/-window days of target DOY across years
    td=doy(target)
    vals=[]
    for d,v in hist:
        dd=abs(doy(d)-td)
        dd=min(dd,365-dd)
        if dd<=window:
            vals.append(v)
    if not vals: return None
    return sum(vals)/len(vals)

