        hist=[(d,v) for d,v in by_band[b] if d<cut]
        for d,v in by_band[b]:
            if d>=cut:
                p=predict_doy(hist,d,window)
                if p is not None: errs.append((p-v)**2)
    rmse=math.sqrt(sum(errs)/len(errs))
    print("window",window,"rmse",round(rmse,4),"n",len(errs))
