def solve(A,b):
    n=len(A); M=[row[:]+[b[i]] for i,row in enumerate(A)]
    for c in range(n):
        p=max(range(c,n),key=lambda r:abs(M[r][c]))
        M[c],M[p]=M[p],M[c]
        pv=M[c][c]
        for k in range(c,n+1): M[c][k]/=pv
        for r in range(n):
            if r==c: continue
            f=M[r][c]
            for k in range(c,n+1): M[r][k]-=f*M[c][k]
    return [M[i][n] for i in range(n)]

def fit_fourier(doy, y, K):
    # design: 1, sin/cos for k=1..K
    X=[]
    for d in doy:
        row=[1.0]
        for k in range(1,K+1):
            row.append(math.sin(2*math.pi*k*d/365.25))
            row.append(math.cos(2*math.pi*k*d/365.25))
