for b in series: series[b].sort()

def design(dates, t0, nharm, trend):
    X=[]
    for d in dates:
        doy = d.timetuple().tm_yday
        ang = 2*math.pi*doy/365.25
        row=[1.0]
        for k in range(1,nharm+1):
            row.append(math.sin(k*ang)); row.append(math.cos(k*ang))
        if trend: row.append((d-t0).days/365.25)
        X.append(row)
    return X
def solve(X,y):
    n=len(X[0]); A=[[0.0]*n for _ in range(n)]; b=[0.0]*n
    for xi,yi in zip(X,y):
        for i in range(n):
            b[i]+=xi[i]*yi
            for j in range(n): A[i][j]+=xi[i]*xi[j]
    for i in range(n): A[i][i]+=1e-6
    for i in range(n):
        p=max(range(i,n),key=lambda r:abs(A[r][i])); A[i],A[p]=A[p],A[i]; b[i],b[p]=b[p],b[i]
        for r in range(i+1,n):
            f=A[r][i]/A[i][i]
            for c in range(i,n): A[r][c]-=f*A[i][c]
            b[r]-=f*b[i]
    x=[0.0]*n
    for i in range(n-1,-1,-1):
        x[i]=(b[i]-sum(A[i][j]*x[j] for j in range(i+1,n)))/A[i][i]
    return x
def predict(x,dates,t0,nharm,trend):
    return [sum(a*b for a,b in zip(xi,x)) for xi in design(dates,t0,nharm,trend)]

