def doy(d): return d.timetuple().tm_yday
def circdiff(a,b):
    d=abs(a-b); return min(d,365-d)

def solve(A,y):
    n=len(A[0]); 
    M=[[sum(A[k][i]*A[k][j] for k in range(len(A))) for j in range(n)]+[sum(A[k][i]*y[k] for k in range(len(A)))] for i in range(n)]
    for i in range(n):
        p=max(range(i,n),key=lambda r:abs(M[r][i]))
        M[i],M[p]=M[p],M[i]
        pv=M[i][i]
        if abs(pv)<1e-12: return None
        for c in range(i,n+1): M[i][c]/=pv
        for r in range(n):
            if r!=i:
                f=M[r][i]
                for c in range(i,n+1): M[r][c]-=f*M[i][c]
    return [M[i][n] for i in range(n)]

def harmonic(hist, td, K=2, trend=True):
    # features: 1, sin/cos annual harmonics, optional linear time (years since start)
    t0=hist[0][0]
    A=[];y=[]
    for d,v in hist:
        frac=doy(d)/365.25*2*math.pi
        row=[1.0]
        for k in range(1,K+1):
            row.append(math.sin(k*frac)); row.append(math.cos(k*frac))
        if trend: row.append((d-t0).days/365.25)
        A.append(row); y.append(v)
    coef=solve(A,y)
    if coef is None: return None
    frac=doy(td)/365.25*2*math.pi
    row=[1.0]
    for k in range(1,K+1):
        row.append(math.sin(k*frac)); row.append(math.cos(k*frac))
    if trend: row.append((td-t0).days/365.25)
    return sum(c*r for c,r in zip(coef,row))

cutoff=datetime.date(2023,10,1)
for K in [1,2,3]:
  for trend in [True,False]:
    print(f"=== harmonic K={K} trend={trend}")
    for b in bands:
        hist=[(d,v) for d,v in series[b] if d<cutoff]
        test=[(d,v) for d,v in series[b] if d>=cutoff]
        errs=[]
        for d,v in test:
            p=harmonic(hist,d,K,trend)
            if p is not None: errs.append(abs(p-v))
        print(b, round(statistics.mean(errs),2) if errs else None)
