rows=list(csv.DictReader(open("data.csv")))
series=defaultdict(list)
for r in rows:
    d=datetime.date.fromisoformat(r["date"])
    series[r["band"]].append((d,float(r["y"])))
for b in series: series[b].sort()
bands=sorted(series)

def clean(s):
    vals=[v for _,v in s]
    med=sorted(vals)[len(vals)//2]
    mad=sorted(abs(v-med) for v in vals)[len(vals)//2] or 1
    out=[]
    for i,(d,v) in enumerate(s):
        lo=max(0,i-3); hi=min(len(s),i+4)
        loc=sorted(x for _,x in s[lo:hi])
        lm=loc[len(loc)//2]
        if abs(v-lm) > 8*mad and abs(v-lm)>0.5*abs(lm):
            out.append((d,lm))
        else:
            out.append((d,v))
    return out

clean_series={b:clean(series[b]) for b in bands}

def doy(d): return d.timetuple().tm_yday
def interp_year(s, yr, td):
    pts=sorted((doy(d),v) for d,v in s if d.year==yr)
    if not pts: return None
    if td<=pts[0][0]: return pts[0][1]
    if td>=pts[-1][0]: return pts[-1][1]
    for i in range(len(pts)-1):
        if pts[i][0]<=td<=pts[i+1][0]:
            x0,y0=pts[i]; x1,y1=pts[i+1]
            return y0 if x1==x0 else y0+(y1-y0)*(td-x0)/(x1-x0)
    return pts[-1][1]

def predict(s, target_date, use_years):
    td=doy(target_date)
    vals=[interp_year(s,yr,td) for yr in use_years]
    vals=[v for v in vals if v is not None]
    return sum(vals)/len(vals) if vals else None

# backtest 2024 using 2021-2023, cleaned
