        if d.year==2024:
            p=predict(s,d,[2021,2022,2023])
            if p is not None: errs.append((p-v)**2)
    rmse=math.sqrt(sum(errs)/len(errs))
    meanv=sum(v for _,v in s)/len(s)
    print(f"{b:5s} rmse={rmse:8.3f} mean={meanv:8.3f} rel={rmse/abs(meanv):.3f}")
