def med(c): return statistics.median(v for _,v in c)
def mean(c): return sum(v for _,v in c)/len(c)
def recw(c):
    # weight by recency: year fraction
    ws=[]; vs=[]
    for d,v in c:
        yr=datetime.date.fromisoformat(d).year
        w=1.0+ (yr-2020)*0.5
        ws.append(w); vs.append(v)
    return sum(w*v for w,v in zip(ws,vs))/sum(ws)
def loclin(c,tdoy):
    # local linear in doy
    if len(c)<3: return med(c)
    xs=[]; ys=[]
    for d,v in c:
        dd=doy(d); off=dd-tdoy
        if off>182: off-=365
        if off<-182: off+=365
        xs.append(off); ys.append(v)
    n=len(xs); mx=sum(xs)/n; my=sum(ys)/n
    sxx=sum((x-mx)**2 for x in xs); sxy=sum((x-mx)*(y-my) for x,y in zip(xs,ys))
    if sxx<1e-9: return my
    b=sxy/sxx; return my+b*(0-mx)

def trim(c):
    vs=sorted(v for _,v in c)
    if len(vs)>=5:
        # drop top/bottom 10%
        k=max(1,len(vs)//10)
        vs=vs[k:-k]
    return statistics.median(vs)

