import csv, datetime, statistics, math

def load(path="data.csv"):
    rows=list(csv.DictReader(open(path)))
    bands=sorted({r["band"] for r in rows})
    data={b:[] for b in bands}
    for r in rows:
        d=datetime.date.fromisoformat(r["date"])
        data[r["band"]].append((d, float(r["y"])))
    for b in bands: data[b].sort()
    return data

def clean(series, k=2.5):
    vals=[v for _,v in series]; keep=[]; n=len(vals)
    for i,(d,v) in enumerate(series):
        lo=max(0,i-3); hi=min(n,i+4)
        win=[vals[j] for j in range(lo,hi) if j!=i]
        med=statistics.median(win)
        mad=statistics.median([abs(x-med) for x in win]) or 1e-9
        if abs(v-med) <= k*1.4826*mad + 1e-9: keep.append((d,v))
    return keep

def solve(A,b):
    n=len(A[0])
    AtA=[[sum(A[k][i]*A[k][j] for k in range(len(A))) for j in range(n)] for i in range(n)]
    Atb=[sum(A[k][i]*b[k] for k in range(len(A))) for i in range(n)]
    for i in range(n): AtA[i][i]+=1e-8
    M=[AtA[i][:]+[Atb[i]] for i in range(n)]
    for c in range(n):
        p=max(range(c,n), key=lambda r: abs(M[r][c]))
        M[c],M[p]=M[p],M[c]
        pv=M[c][c]
        if abs(pv)<1e-12: continue
        for r in range(n):
            if r!=c:
                f=M[r][c]/pv
                for k in range(c,n+1): M[r][k]-=f*M[c][k]
    return [M[i][n]/M[i][i] if abs(M[i][i])>1e-12 else 0.0 for i in range(n)]

def design(dates, t0, K, trend=True):
    A=[]
    for d in dates:
        t=(d-t0).days/365.25
        row=[1.0]
        if trend: row.append(t)
        for k in range(1,K+1):
            row.append(math.sin(2*math.pi*k*t))
            row.append(math.cos(2*math.pi*k*t))
        A.append(row)
    return A

def fit_predict(train, pred_dates, K=2, trend=True):
    t0=train[0][0]
    A=design([d for d,_ in train], t0, K, trend)
    b=[v for _,v in train]
    coef=solve(A,b)
    Ap=design(pred_dates, t0, K, trend)
    return [sum(c*x for c,x in zip(coef,row)) for row in Ap], coef

def evalrel(K, trend, log=False):
    data=load()
    out={}
    for b,ser in data.items():
        c=clean(ser)
        errs=[]
        for y in [2021,2022,2023,2024]:
            tr=[(d,v) for d,v in c if d.year!=y]
            te=[(d,v) for d,v in c if d.year==y]
            if len(te)<5: continue
            if log:
                tr=[(d,math.log(v)) for d,v in tr]
                pr,_=fit_predict(tr,[d for d,_ in te],K,trend)
                pr=[math.exp(p) for p in pr]
            else:
                pr,_=fit_predict(tr,[d for d,_ in te],K,trend)
            errs += [abs(p-v) for p,(_,v) in zip(pr,te)]
        scale=statistics.mean([v for _,v in c])
        out[b]=statistics.mean(errs)/abs(scale)
    return out
